import { ApplicationStrip } from "@/components/gate/ApplicationStrip";

type ResolvedHomePageContent = Required<HomePageContent>;

const defaultContent: ResolvedHomePageContent = canonicalHomePageContent;

export function HomePage({ content }: { content?: HomePageContent }) {
  const presentContent = Object.fromEntries(
    Object.entries(content ?? {}).filter(([, value]) => value !== null && value !== undefined),
  );
  const resolvedContent: ResolvedHomePageContent = {
    ...defaultContent,
    ...presentContent,
    heroWords: content?.heroWords?.filter(Boolean).length ? content.heroWords.filter(Boolean) : defaultContent.heroWords,
    ctaWords: content?.ctaWords?.filter(Boolean).length ? content.ctaWords.filter(Boolean) : defaultContent.ctaWords,
    scenarioCards: content?.scenarioCards?.length ? content.scenarioCards : defaultContent.scenarioCards,
  };
  return (<><div className="page-wrapper whitegate-home"><HomeGlobalStyles /><HomeNav /><HomeNavMobileBehavior /><HomeMainWrapper content={resolvedContent} /></div></>);
}

