function HomeTestimonialSection({ content }: { content: ResolvedHomePageContent }) {
  const scenarios = content.scenarioCards;
  return (
    <section className="section testimonial" aria-labelledby="home-scenarios-title">
      <div className="padding-global"><div className="container-base"><div className="testimonial-layout">
        <div className="eyebrow-section"><div className="eyebrow-main"><div className="eyebrow-text">[n.06/08]</div><div className="eyebrow-line small"></div><div className="eyebrow-text">&gt; örnek uygulamalar</div></div><div className="eyebrow-line"></div></div>
        <div className="testimonial-slider home-scenario-slider">
          <div className="testimonial-heading"><h2 id="home-scenarios-title" className="heading-style-h3"><span className="heading-slash">/</span> Ekibinizin önündeki hangi işi AI üstlenebilir? <span className="heading-slash">/</span></h2></div>
          <div className="testimonial-slider-mask" role="region" aria-label="Örnek AI uygulaması kartları" tabIndex={0}>
            {scenarios.map((scenario, index) => (
              <article className="testimonial-slide" key={scenario.number}>
                <a href={scenario.href} className={"testimonial-slide-inner home-scenario-card " + (index % 2 ? "home-scenario-card-light" : "")}>
                  <div className="home-scenario-art"><img src={scenario.image} loading="lazy" alt={scenario.title + " görseli"} /></div>
                  <div className="home-scenario-body">
                    <div className="home-scenario-meta"><span>// {scenario.number} · {scenario.team}</span><span>ÖRNEK SENARYO</span></div>
                    <h3>{scenario.title}</h3>
                    <p>{scenario.text}</p>
                    <div className="home-scenario-bottom"><span>{scenario.steps}</span><span aria-hidden="true">↗</span></div>
                  </div>
                </a>
              </article>
            ))}
          </div>
          <div className="home-scenario-controls"><span>↔ KARTLARI KEŞFET</span><div><button type="button" className="testimonial-slider-btn left" aria-label="Önceki örnek">←</button><button type="button" className="testimonial-slider-btn right" aria-label="Sonraki örnek">→</button></div></div>
        </div>
      </div></div></div>
    </section>
  );
}

